module indoorienteering (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [7:0] L,\n    input [7:0] dist_00, dist_01, dist_02, dist_03,\n    input [7:0] dist_10, dist_11, dist_12, dist_13,\n    input [7:0] dist_20, dist_21, dist_22, dist_23,\n    input [7:0] dist_30, dist_31, dist_32, dist_33,\n    output reg possible,\n    output reg done\n);\n    // State definitions\n    localparam [1:0] IDLE     = 2'd0;\n    localparam [1:0] COMPARE  = 2'd1;\n    localparam [1:0] FINISH   = 2'd2;\n    \n    reg [1:0] state;\n    reg [2:0] perm_index;\n    reg found;\n    wire [15:0] L_ext = {8'd0, L};\n    wire [2:0] max_perm = (n == 3'd2) ? 3'd1 :\n                          (n == 3'd3) ? 3'd2 :\n                          (n == 3'd4) ? 3'd6 : 3'd0;\n    \n    // Distance array\n    wire [7:0] dist [3:0][3:0];\n    assign dist[0][0] = dist_00; assign dist[0][1] = dist_01; assign dist[0][2] = dist_02; assign dist[0][3] = dist_03;\n    assign dist[1][0] = dist_10; assign dist[1][1] = dist_11; assign dist[1][2] = dist_12; assign dist[1][3] = dist_13;\n    assign dist[2][0] = dist_20; assign dist[2][1] = dist_21; assign dist[2][2] = dist_22; assign dist[2][3] = dist_23;\n    assign dist[3][0] = dist_30; assign dist[3][1] = dist_31; assign dist[3][2] = dist_32; assign dist[3][3] = dist_33;\n    \n    // Total distance calculation\n    reg [15:0] total_sum;\n    always @(*) begin\n        total_sum = 16'd0;\n        case (n)\n            3'd2: begin\n                total_sum = dist[0][1] + dist[1][0];\n            end\n            3'd3: begin\n                case (perm_index)\n                    3'd0: total_sum = dist[0][1] + dist[1][2] + dist[2][0];\n                    3'd1: total_sum = dist[0][2] + dist[2][1] + dist[1][0];\n                    default: total_sum = 16'd0;\n                endcase\n            end\n            3'd4: begin\n                case (perm_index)\n                    3'd0: total_sum = dist[0][1] + dist[1][2] + dist[2][3] + dist[3][0];\n                    3'd1: total_sum = dist[0][1] + dist[1][3] + dist[3][2] + dist[2][0];\n                    3'd2: total_sum = dist[0][2] + dist[2][1] + dist[1][3] + dist[3][0];\n                    3'd3: total_sum = dist[0][2] + dist[2][3] + dist[3][1] + dist[1][0];\n                    3'd4: total_sum = dist[0][3] + dist[3][1] + dist[1][2] + dist[2][0];\n                    3'd5: total_sum = dist[0][3] + dist[3][2] + dist[2][1] + dist[1][0];\n                    default: total_sum = 16'd0;\n                endcase\n            end\n            default: total_sum = 16'd0;\n        endcase\n    end\n    \n    // State Machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            perm_index <= 3'd0;\n            found <= 1'b0;\n            done <= 1'b0;\n            possible <= 1'b0;\n        end else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= COMPARE;\n                        perm_index <= 3'd0;\n                        found <= 1'b0;\n                    end\n                end\n                \n                COMPARE: begin\n                    // Check if current total equals L\n                    if (total_sum == L_ext) found <= 1'b1;\n                    \n                    // Next permutation\n                    if (perm_index < (max_perm - 3'd1)) begin\n                        perm_index <= perm_index + 3'd1;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    possible <= found;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule